"""The response object of OpenAI's Responses API."""

from __future__ import annotations

from typing import Annotated, Any, Literal

from pydantic import Discriminator, Field, Tag

from ai_api.types.base import BaseAPIType
from ai_api.types.unknown import UNKNOWN, BaseUnknown, by_type


class OutputText(BaseAPIType):
    """Text generated by the model.

    Attributes:
        type: Always ``"output_text"``.
        text: The text.
        annotations: Citations and file paths in the text, as sent.
        logprobs: Token log probabilities; ``None`` when not requested.
    """

    __upstream_schema__ = "ResponseOutputText"

    type: Literal["output_text"] = "output_text"
    text: str
    annotations: list[dict[str, Any]] = Field(default_factory=list)
    logprobs: list[dict[str, Any]] | None = None


class OutputRefusal(BaseAPIType):
    """The model refused to answer.

    Attributes:
        type: Always ``"refusal"``.
        refusal: The explanation of the refusal.
    """

    __upstream_schema__ = "ResponseOutputRefusal"

    type: Literal["refusal"] = "refusal"
    refusal: str


class UnknownContent(BaseUnknown):
    """A content part of a type the library does not model yet."""


type OutputContent = Annotated[
    Annotated[OutputText, Tag("output_text")]
    | Annotated[OutputRefusal, Tag("refusal")]
    | Annotated[UnknownContent, Tag(UNKNOWN)],
    Discriminator(
        by_type({"output_text": "output_text", "refusal": "refusal"})
    ),
]
"""A content part of an output message, told apart by ``type``."""


class OutputMessage(BaseAPIType):
    """A message from the model, one of the output items.

    Attributes:
        type: Always ``"message"``.
        id: Item identifier.
        role: Always ``"assistant"``.
        status: ``"in_progress"``, ``"completed"`` or ``"incomplete"``.
        content: Text and refusal parts.
        phase: ``"commentary"`` or ``"final_answer"``, if set.
    """

    __upstream_schema__ = "ResponseOutputMessage"

    type: Literal["message"] = "message"
    id: str
    role: Literal["assistant"] = "assistant"
    status: str
    content: list[OutputContent] = Field(default_factory=list)
    phase: str | None = None


class UnknownOutputItem(BaseUnknown):
    """An output item the library does not model yet.

    Reasoning, tool calls and the other item types are kept whole, with
    all their fields as extra fields.
    """


type OutputItem = Annotated[
    Annotated[OutputMessage, Tag("message")]
    | Annotated[UnknownOutputItem, Tag(UNKNOWN)],
    Discriminator(by_type({"message": "message"})),
]
"""An item of ``Response.output``, told apart by ``type``."""


class InputTokensDetails(BaseAPIType):
    """Breakdown of the input tokens.

    Attributes:
        cached_tokens: Tokens read from the prompt cache.
        cache_write_tokens: Tokens written to the prompt cache.
    """

    __upstream_schema__ = "InputTokensDetails"

    cached_tokens: int | None = None
    cache_write_tokens: int | None = None


class OutputTokensDetails(BaseAPIType):
    """Breakdown of the output tokens.

    Attributes:
        reasoning_tokens: Tokens spent on reasoning.
    """

    __upstream_schema__ = "OutputTokensDetails"

    reasoning_tokens: int | None = None


class ResponseUsage(BaseAPIType):
    """Token counts of a response.

    Attributes:
        input_tokens: Tokens in the input.
        input_tokens_details: Breakdown of the input tokens.
        output_tokens: Tokens generated, reasoning included.
        output_tokens_details: Breakdown of the output tokens.
        total_tokens: Input and output together.
    """

    __upstream_schema__ = "ResponseUsage"

    input_tokens: int
    input_tokens_details: InputTokensDetails | None = None
    output_tokens: int
    output_tokens_details: OutputTokensDetails | None = None
    total_tokens: int


class ResponseError(BaseAPIType):
    """Why a response failed.

    ``code`` is a plain string: OpenAI documents a list of codes, but new
    ones appear, and an unknown code must not fail the whole response.

    Attributes:
        code: Error code, such as ``"server_error"``.
        message: Description of the error.
        param: Parameter the error is about, if any.
        type: Error type, if any.
    """

    __upstream_schema__ = "ResponseError"

    code: str
    message: str
    param: str | None = None
    type: str | None = None


class IncompleteDetails(BaseAPIType):
    """Why a response is incomplete.

    Attributes:
        reason: Such as ``"max_output_tokens"`` or ``"content_filter"``.
    """

    __upstream_schema__ = "IncompleteDetails"

    reason: str | None = None


class Response(BaseAPIType):
    """A response of the Responses API.

    Only the fields needed to read a generation are modeled; the request
    settings echoed back (tools, reasoning, truncation and so on) are
    ignored. ``status`` is a plain string for the same reason as
    ``ResponseError.code``.

    Attributes:
        id: Response identifier.
        object: Always ``"response"``.
        created_at: Creation time, Unix seconds.
        completed_at: Completion time, only for a completed response.
        status: ``"completed"``, ``"failed"``, ``"in_progress"``,
            ``"cancelled"``, ``"queued"`` or ``"incomplete"``.
        model: Model that generated the response.
        output: Messages, reasoning and tool calls, in order.
        usage: Token counts; ``None`` until the response is finished.
        error: Why the response failed, if it did.
        incomplete_details: Why the response is incomplete, if it is.
        instructions: Instructions the response was generated with.
        metadata: Metadata given with the request.
        previous_response_id: Response this one continues, if any.
    """

    __upstream_schema__ = "Response"

    id: str
    object: Literal["response"] = "response"
    created_at: float
    completed_at: float | None = None
    status: str | None = None
    model: str
    output: list[OutputItem] = Field(default_factory=list)
    usage: ResponseUsage | None = None
    error: ResponseError | None = None
    incomplete_details: IncompleteDetails | None = None
    instructions: str | list[Any] | None = None
    metadata: dict[str, str] | None = None
    previous_response_id: str | None = None

    @property
    def output_text(self) -> str | None:
        """The text of all output messages joined together.

        The Responses API sends no such field (the official SDKs compute
        it the same way), so it is collected from the ``output_text``
        parts of the ``message`` items.

        Returns:
            The joined text, or ``None`` if the output has no text part.
        """
        parts = [
            part.text
            for item in self.output
            if isinstance(item, OutputMessage)
            for part in item.content
            if isinstance(part, OutputText)
        ]
        return "".join(parts) if parts else None
